const rows = $input.all().map(i => i.json).filter(r => r && r.tipo_alerta);
const PRODUCTOR = 'PRODUCTOR_WA_ID';
const iconos = { parto_proximo:'🐣', secado:'🍼', celo_esperado:'❤️', chequear_prenez:'🔍', sanidad:'💉' };
let respuesta;
if (!rows.length) {
  respuesta = '✅ Sin alertas para hoy. Todo al día en el hato.';
} else {
  const lineas = rows.map(r => `${iconos[r.tipo_alerta] || '•'} ${r.arete}${r.nombre ? ' ('+r.nombre+')' : ''}: ${r.detalle}`);
  respuesta = `📊 Alertas del hato (${rows.length})\n\n` + lineas.join('\n');
}
return [{ json: { telefono: PRODUCTOR, respuesta } }];
